use ring_buffer::RingBuffer;

#[test]
fn test_push_and_pop() {
    let mut rb: RingBuffer<i32> = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    assert_eq!(rb.pop(), Some(1));
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), None);
}

#[test]
fn test_overwrite_when_full() {
    let mut rb = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4); // should evict oldest (1)
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), Some(3));
    assert_eq!(rb.pop(), Some(4));
    assert_eq!(rb.pop(), None);
}

#[test]
fn test_len_is_empty_is_full() {
    let mut rb: RingBuffer<&str> = RingBuffer::new(2);
    assert!(rb.is_empty());
    assert!(!rb.is_full());
    rb.push("a");
    assert_eq!(rb.len(), 1);
    assert!(!rb.is_empty());
    assert!(!rb.is_full());
    rb.push("b");
    assert!(rb.is_full());
    assert_eq!(rb.len(), 2);
}

#[test]
fn test_peek_does_not_consume() {
    let mut rb: RingBuffer<i32> = RingBuffer::new(3);
    rb.push(42);
    assert_eq!(rb.peek(), Some(&42));
    assert_eq!(rb.len(), 1); // peek leaves element in place
    assert_eq!(rb.pop(), Some(42));
    assert_eq!(rb.peek(), None);
}

#[test]
fn test_capacity_one() {
    let mut rb = RingBuffer::new(1);
    rb.push(10);
    rb.push(20); // evicts 10
    assert_eq!(rb.pop(), Some(20));
    assert_eq!(rb.pop(), None);
}
